//! Stable app-owned outputs; never rename or overwrite source artwork.
use std::{fs,io::{Read,Write},path::Path};
use serde_json::{Value,json};
use crate::studio_files as disk;
fn registry(root:&Path)->Result<Value,String>{let p=disk::subdir(root,"Studio Link")?.join("storyboard-outputs.json");if !p.exists(){return Ok(json!({"format":"storyboard-outputs-v1","files":{}}))}let r:Value=serde_json::from_slice(&fs::read(p).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;if r["format"]!="storyboard-outputs-v1"{return Err("Invalid Storyboard output registry".into())}Ok(r)}
pub(crate) fn fingerprint(bytes:&[u8])->String{let mut hash=14695981039346656037u64;for b in bytes{hash=(hash^*b as u64).wrapping_mul(1099511628211);}format!("image-v1-{}-{hash:016x}",bytes.len())}
pub(crate) fn file_fingerprint(path:&Path)->Result<String,String>{let mut f=fs::File::open(path).map_err(|e|e.to_string())?;let mut hash=14695981039346656037u64;let mut size=0usize;let mut b=[0;65536];loop{let n=f.read(&mut b).map_err(|e|e.to_string())?;if n==0{break}size+=n;for x in &b[..n]{hash=(hash^*x as u64).wrapping_mul(1099511628211);}}Ok(format!("image-v1-{size}-{hash:016x}"))}
pub(crate) fn unchanged(path:&Path,r:&Value,size:u64,modified:u64)->bool{if !r["fingerprint"].is_string()&&r["size"].as_u64()==Some(size)&&r["modified"].as_u64()==Some(modified){return true}r["fingerprint"].as_str().map(|expected|file_fingerprint(path).map(|s|s==expected).unwrap_or(false)).unwrap_or(false)}
fn validate(root:&Path,path:&str,project:&str,key:&str,r:&Value)->Result<(),String>{let rel=disk::relative(path)?;if project.is_empty()||key.is_empty(){return Err("Missing export ownership".into())}let target=root.join(rel);if let Some(parent)=target.parent(){if parent.exists()&&!parent.canonicalize().map_err(|e|e.to_string())?.starts_with(root){return Err("Export folder points outside the project".into())}}let record=&r["files"][path];if !record.is_null()&&(record["project"]!=project||(record["key"]!=key))&&(target.exists()||record["project"]!=project){return Err(format!("{path} is reserved for another export. Change the naming pattern or choose another destination."))}if target.exists(){let real=target.canonicalize().map_err(|e|e.to_string())?;if !real.starts_with(root)||fs::symlink_metadata(&target).map_err(|e|e.to_string())?.file_type().is_symlink(){return Err("Output file points outside its destination".into())}let(size,modified)=disk::metadata(&target)?;if record["project"]!=project||(record["key"]!=key)||!unchanged(&target,record,size,modified){return Err(format!("{path} already exists and was not saved by this export, or was changed outside the app. Choose another filename or remove it yourself."))}}Ok(())}
pub fn check(root:&Path,path:&str,project:&str,key:&str)->Result<(),String>{validate(root,path,project,key,&registry(root)?)}
pub fn retire_timeline_maps(root:&Path,project:&str)->Result<(),String>{
 // Caller holds the workflow lock.
 let mut records=registry(root)?;let mut retired=Vec::new();
 if let Some(files)=records["files"].as_object(){for(path,record)in files{
  let key=record["key"].as_str().unwrap_or("");
  if path.starts_with("Studio Link/")&&path.ends_with("_map.json")&&key.starts_with("timeline-map:")&&record["project"]==project&&validate(root,path,project,key,&records).is_ok(){
   let target=root.join(disk::relative(path)?);if !target.exists()||fs::remove_file(target).is_ok(){retired.push(path.clone());}
  }
 }}
 if retired.is_empty(){return Ok(())}for path in retired{records["files"].as_object_mut().unwrap().remove(&path);}
 disk::atomic_json(&disk::subdir(root,"Studio Link")?,"storyboard-outputs.json",&records.to_string())
}
pub fn write(root:&Path,path:&str,bytes:&[u8],project:&str,key:&str)->Result<String,String>{
 if bytes.len()>128*1024*1024{return Err("Export exceeds 128 MB".into())}let link=disk::subdir(root,"Studio Link")?;let _workflow=crate::media_organization::lock(root)?;
 let mut r=registry(root)?;validate(root,path,project,key,&r)?;let target=root.join(disk::relative(path)?);if target.is_file()&&fs::read(&target).map_err(|e|e.to_string())?==bytes{return Ok(path.to_string())}let parent=target.parent().ok_or("Invalid output folder")?;if let Some(rel)=Path::new(path).parent(){if !rel.as_os_str().is_empty(){disk::subdir(root,&rel.to_string_lossy())?;}}
 let tmp=parent.join(format!(".ss-output-{}-{}.tmp",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos()));let mut f=fs::OpenOptions::new().write(true).create_new(true).open(&tmp).map_err(|e|e.to_string())?;f.write_all(bytes).and_then(|_|f.sync_all()).map_err(|e|e.to_string())?;drop(f);
 if let Err(e)=disk::replace_file(&tmp,&target){let _=fs::remove_file(&tmp);return Err(e)}
 let(size,modified)=disk::metadata(&target)?;r["files"][path]=json!({"project":project,"key":key,"size":size,"modified":modified,"fingerprint":fingerprint(bytes)});disk::atomic_json(&link,"storyboard-outputs.json",&r.to_string())?;Ok(path.to_string())
}
#[cfg(test)]mod tests{use super::*;#[test]fn updates_owned_file_and_blocks_collisions(){let root=std::env::temp_dir().join(format!("owned-output-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir(&root).unwrap();let root=root.canonicalize().unwrap();write(&root,"Ch/001.png",b"one","p","card1").unwrap();write(&root,"Ch/001.png",b"two","p","card1").unwrap();assert_eq!(fs::read(root.join("Ch/001.png")).unwrap(),b"two");assert!(!root.join("Ch/001_002.png").exists());assert!(write(&root,"Ch/001.png",b"bad","p","card2").is_err());fs::write(root.join("user.png"),b"original").unwrap();assert!(write(&root,"user.png",b"bad","p","user").is_err());assert!(write(&root,"../bad",b"bad","p","user").is_err());fs::remove_dir_all(root).unwrap();}}

pub fn retire(root:&Path,path:&str,project:&str,card_id:&str,source_id:&str,expected:Option<&str>)->Result<(),String>{let _workflow=crate::media_organization::lock(root)?;let mut r=registry(root)?;let key=r["files"][path]["key"].as_str().ok_or("The previous export is not tracked")?.to_string();let allowed=expected.map(|e|e==key).unwrap_or_else(||key.starts_with(&format!("drawing:{card_id}:"))||key.starts_with(&format!("drawing:{source_id}:"))||key==format!("export:{path}"));if !allowed||!path.ends_with(".png"){return Err("The previous file belongs to another drawing".into())}validate(root,path,project,&key,&r)?;let target=root.join(disk::relative(path)?);if target.exists(){fs::remove_file(target).map_err(|e|e.to_string())?;}r["files"].as_object_mut().unwrap().remove(path);disk::atomic_json(&disk::subdir(root,"Studio Link")?,"storyboard-outputs.json",&r.to_string())}
#[cfg(test)]mod audit_tests{use super::*;fn temp()->std::path::PathBuf{let r=std::env::temp_dir().join(format!("own-audit-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(&r).unwrap();r}
#[test]fn missing_reservation_can_be_reused(){let r=temp();write(&r,"Ch/1.png",b"old","p","drawing:old:0").unwrap();fs::remove_file(r.join("Ch/1.png")).unwrap();write(&r,"Ch/1.png",b"new","p","drawing:new:0").unwrap();assert_eq!(fs::read(r.join("Ch/1.png")).unwrap(),b"new");assert!(write(&r,"Ch/1.png",b"bad","p","drawing:other:0").is_err());fs::remove_dir_all(r).unwrap();}
#[test]fn content_identity_survives_date_drift_but_protects_external_artwork(){let r=temp();write(&r,"Ch/1.png",b"rough","p","drawing:one:0").unwrap();let mut v=registry(&r).unwrap();v["files"]["Ch/1.png"]["modified"]=json!(0);disk::atomic_json(&r.join("Studio Link"),"storyboard-outputs.json",&v.to_string()).unwrap();write(&r,"Ch/1.png",b"rough","p","drawing:one:0").unwrap();fs::write(r.join("Ch/1.png"),b"external cleanup").unwrap();assert!(write(&r,"Ch/1.png",b"rough","p","drawing:one:0").is_err());assert_eq!(fs::read(r.join("Ch/1.png")).unwrap(),b"external cleanup");fs::remove_dir_all(r).unwrap();}}
